insert into public."episode" ("summary", "theme_color", "vimeo_url", "keywords", "marketplace_category", "title", "thumbnail_url", "triggers", "platform", "assigned_floors", "youtube_url", "category", "status", id, created_date, updated_date, created_by) values ('A World Reimagined Through Storytelling', '#F59E0B', 'https://vimeo.com/1169534047?share=copy&fl=sv&fe=ci', '["freedom", "Hate", "Love", "Life", "Real World", "Black Art"]'::jsonb, 'other', 'GlobeHouse Tv Official Trailer ', 'https://base44.app/api/apps/6999eeb5400ab46cf574d543/files/public/6999eeb5400ab46cf574d543/6ca29f226_TheBklackJournal.png', '[{"prompt_text": "Find Recommended Readings", "bounding_box": null, "trigger_type": "buyscreen_only", "confessional_video_url": "", "product_image_url": "https://base44.app/api/apps/6999eeb5400ab46cf574d543/files/mp/public/6999eeb5400ab46cf574d543/7b45d456d_71cSmGSNUEL_SL1500_.jpg", "product_price": "$2.99", "product_name": "The Science of Racism Everything You Need to Know but Probably Don''t\u2014Yet", "product_quote": "", "confessional_duration": 4, "duration": null, "model_url": "", "shop_url": "https://www.amazon.com/Science-Racism-Everything-Probably-Dont_Yet/dp/1419774379", "detection_status": null, "confidence_score": null, "product_brand": "Keon West", "product_description": "In The Science of Racism, social psychologist Keon West corrects that idea, moving this urgent conversation beyond anecdote and polemic in search of conclusive answers and solutions.\n\nStarting with a fascinating look at experiments around race in hiring, Dr. West brilliantly and methodically walks readers through our comprehensive understanding of this controversial topic. He looks at how racism impacts every stage and all facets of life, from birth to death, in education, work and business, friendships and relationships, police and the justice system, and healthcare.\n\nHe also looks at the challenges around studying these questions and the ways we can uncover the truth, and then where we go from here: why unconscious bias training can actually make things worse, and what systems and techniques can lead us to a more equitable future.\n", "timestamp": 2, "model_embed_code": ""}, {"prompt_text": "Find the deeper meaning.", "bounding_box": null, "trigger_type": "buyscreen_only", "confessional_video_url": "", "product_image_url": "https://base44.app/api/apps/6999eeb5400ab46cf574d543/files/mp/public/6999eeb5400ab46cf574d543/b64e29319_HonorMoviePosterSquare.png", "product_price": "Free", "product_name": "Honor Among Men Truth", "product_quote": "", "confessional_duration": 4, "duration": null, "model_url": "", "shop_url": "https://youtu.be/fmYgqgC-UJA?si=XkI6B28eK1pX2X5K", "detection_status": null, "confidence_score": null, "product_brand": "Honor Among Men", "product_description": "Podcast defining  what is truth", "timestamp": 17, "model_embed_code": ""}]'::jsonb, 'globehouse', '["published", "tv_shows"]'::jsonb, '', 'other', 'published', '69a525757e6e0af83719effd', '2026-03-02T05:51:49.253000', '2026-09-10T03:18:25.765000', 'finwardblackwellent@gmail.com') on conflict (id) do nothing;
