insert into public."product_registry" ("additional_images", "short_description", "product_url", "is_active", "display_price", "image_url", "migrated_from_episode", "character_quote", "description", "merchant_id", "inventory", "inventory_status", "tags", "model_url", "price", "total_revenue", "name", "sku", "category", "total_sales", "brand", "is_featured", id, created_date, updated_date, created_by) values ('[]'::jsonb, 'In The Science of Racism, social psychologist Keon West corrects that idea, moving this urgent conversation beyond anecdote and polemic in search of conclusive answers and solutions.

Starting with a fascinating look at experiments around race in hiring, Dr. West brilliantly and methodically walks readers through our comprehensive understanding of this controversial topic. He looks at how racism impacts every stage and all facets of life, from birth to death, in education, work and business, friendships and relationships, police and the justice system, and healthcare.

He also looks at the challenges around studying these questions and the ways we can uncover the truth, and then where we go from here: why unconscious bias training can actually make things worse, and what systems and techniques can lead us to a more equitable future.
', 'https://www.amazon.com/Science-Racism-Everything-Probably-Dont_Yet/dp/1419774379', true, '$2.99', 'https://base44.app/api/apps/6999eeb5400ab46cf574d543/files/mp/public/6999eeb5400ab46cf574d543/7b45d456d_71cSmGSNUEL_SL1500_.jpg', '69a525757e6e0af83719effd', '', 'In The Science of Racism, social psychologist Keon West corrects that idea, moving this urgent conversation beyond anecdote and polemic in search of conclusive answers and solutions.

Starting with a fascinating look at experiments around race in hiring, Dr. West brilliantly and methodically walks readers through our comprehensive understanding of this controversial topic. He looks at how racism impacts every stage and all facets of life, from birth to death, in education, work and business, friendships and relationships, police and the justice system, and healthcare.

He also looks at the challenges around studying these questions and the ways we can uncover the truth, and then where we go from here: why unconscious bias training can actually make things worse, and what systems and techniques can lead us to a more equitable future.
', '6a31353dadc7be109bbfe5b4', 0, 'in_stock', '[]'::jsonb, '', 299, 0, 'The Science of Racism Everything You Need to Know but Probably Don''t—Yet', null, 'other', 0, 'Keon West', false, '6a313544976ff83b19c552e0', '2026-06-16T11:36:36.804000', '2026-06-16T11:36:36.804000', 'service+e23a580c-a159-4ea8-95f9-a18b8a372b31@no-reply.base44.com') on conflict (id) do nothing;
